 useEffect(()=>{if(!projectId)return;const id=projectId;let retry=0,last=0,ws:WebSocket|undefined,dead=false,reconnectTimer:ReturnType<typeof setTimeout>|undefined;setConnection("connecting");const connect=()=>{if(dead)return;const base=(window as any).auraDesktop?.wsUrl||API.replace(/^http/,"ws")||location.origin.replace(/^http/,"ws");ws=new WebSocket(`${base}/api/projects/${id}/events?afterEventId=${last}`);ws.onopen=()=>{if(dead)return;retry=0;setConnection("connected")};ws.onmessage=e=>{if(dead||session.current.identity?.projectId!==id)return;const event=JSON.parse(e.data);if(event.eventId<=last)return;last=event.eventId;if(event.type==="revision.committed"||event.type==="project.ready")load(id)};ws.onclose=()=>{if(dead)return;if(retry++<6){setConnection("reconnecting");reconnectTimer=setTimeout(connect,Math.min(1000*2**retry,15000))}else setConnection("paused")}};connect();return()=>{dead=true;if(reconnectTimer)clearTimeout(reconnectTimer);if(ws){ws.onopen=ws.onmessage=ws.onclose=null;ws.close()}}},[projectId]);
